"use client";
import * as React from "react";
import { Drawer as DrawerPrimitive } from "vaul";

import { cn } from "@/utils/class-names";

function Drawer({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Root>) {
  return <DrawerPrimitive.Root data-slot="drawer" {...props} />;
}

function DrawerTrigger({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Trigger>) {
  return <DrawerPrimitive.Trigger data-slot="drawer-trigger" {...props} />;
}

function DrawerPortal({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Portal>) {
  return <DrawerPrimitive.Portal data-slot="drawer-portal" {...props} />;
}

function DrawerClose({
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Close>) {
  return <DrawerPrimitive.Close data-slot="drawer-close" {...props} />;
}

function DrawerOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Overlay>) {
  return (
    <DrawerPrimitive.Overlay
      data-slot="drawer-overlay"
      className={cn("aura-overlay z-50", className)}
      {...props}
    />
  );
}

function DrawerContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Content>) {
  return (
    <DrawerPortal data-slot="drawer-portal">
      <DrawerOverlay />
      <DrawerPrimitive.Content
        data-slot="drawer-content"
        className={cn(
          "fixed inset-x-0 bottom-0 z-50 mt-8 flex h-auto flex-col rounded-t-[10px] border border-gray-6 bg-gray-1",
          className
        )}
        {...props}
      >
        <div className="mx-auto mt-1 h-0.5 w-8 rounded-full bg-gray-3" />
        {children}
      </DrawerPrimitive.Content>
    </DrawerPortal>
  );
}

function DrawerHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-header"
      className={cn("grid gap-0.5 p-1.5 text-center sm:text-left", className)}
      {...props}
    />
  );
}

function DrawerFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-footer"
      className={cn("mt-auto flex flex-col gap-1 p-1.5", className)}
      {...props}
    />
  );
}

function DrawerTitle({
  className,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Title>) {
  return (
    <DrawerPrimitive.Title
      data-slot="drawer-title"
      className={cn(
        "text-lg font-semibold leading-none tracking-tight text-gray-12",
        className
      )}
      {...props}
    />
  );
}

function DrawerDescription({
  className,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Description>) {
  return (
    <DrawerPrimitive.Description
      data-slot="drawer-description"
      className={cn("text-sm text-gray-11", className)}
      {...props}
    />
  );
}

export {
  Drawer,
  DrawerPortal,
  DrawerOverlay,
  DrawerTrigger,
  DrawerClose,
  DrawerContent,
  DrawerHeader,
  DrawerFooter,
  DrawerTitle,
  DrawerDescription,
};

:root {
  --aura-overlay: rgb(16 11 33 / 0.08);
}

@keyframes aura-overlay-show {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes aura-overlay-hide {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

.aura-overlay {
  position: fixed;
  inset: 0;
  background-color: var(--aura-overlay);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
}

.aura-overlay[data-state="open"] {
  animation: aura-overlay-show 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

/*
 * vaul injects an unlayered 500ms fadeIn/fadeOut on [data-vaul-overlay].
 * !important keeps the 150ms fade when this file is imported inside a layer.
 */
.aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="open"] {
  animation: aura-overlay-show 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="closed"] {
  animation: aura-overlay-hide 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.aura-overlay[data-starting-style],
.aura-overlay[data-ending-style] {
  opacity: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .aura-overlay:is([data-open], [data-closed], [data-starting-style], [data-ending-style]) {
    transition: opacity 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .aura-overlay,
  .aura-overlay[data-state="open"],
  .aura-overlay[data-state="closed"],
  .aura-overlay[data-starting-style],
  .aura-overlay[data-ending-style],
  .aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="open"],
  .aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="closed"] {
    animation: none !important;
    transition: none;
    opacity: 1;
  }
}
